CREATE OR REPLACE FUNCTION calculate_cpi(
    HistSignRating SMALLINT,
    ResearchValRating INTEGER,
    CultScore SMALLINT,
    ConserveStatus TEXT
) RETURNS FLOAT AS $ $
DECLARE
    cpi_value FLOAT;
BEGIN
    -- Map ConserveStatus to its numerical value
    IF ConserveStatus = 'Excellent' THEN
        cpi_value := 1;
    ELSIF ConserveStatus = 'Good' THEN
        cpi_value := 3;
    ELSIF ConserveStatus = 'Fair' THEN
        cpi_value := 5;
    ELSIF ConserveStatus = 'Poor' THEN
        cpi_value := 7;
    ELSIF ConserveStatus = 'Critical' THEN
        cpi_value := 10;
    ELSE
        RAISE EXCEPTION 'Invalid ConserveStatus value';
    END IF;

    -- Calculate CPI using the formula
    cpi_value := (HistSignRating + ResearchValRating + CultScore) * (10 - cpi_value) / 30;

    RETURN cpi_value;
END;
$ $ LANGUAGE plpgsql;

